lee={'tAs':(None,None,None,0.0035,2.141,7.065),'Cd':(None,None,None,0.0030,2.239,7.389),'Cr':(0.0247,0.0132,0.0094,0.0555,2.348,7.748),'Ni':(0.1072,0.1089,0.0113,0.4425,2.679,8.841),'Pb':(0.0135,0.0150,None,0.0604,2.732,9.016)}
