 reason='included primary verification' if s in sources else 'Pending primary recovery and exact banana-specific extraction; retained as discovery candidate, not used for a numerical or causal finding.'
 if 'unaegbu' in s:reason='Primary HTML received but result table not recovered in parsed response; source uses diluted extract mg/L, not fruit mg/kg. Excluded from compatible mass-basis comparisons pending full table and extraction-volume recovery.'
 if 'rahim' in s:reason='Dry-weight source candidate; source-page instrument LOD and fruit-result reconciliation require full primary recovery before admission; no unverified means borrowed.'
